terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# --- Variables ---

variable "project_id" {
  description = "The GCP project ID"
  type        = string
}

variable "region" {
  description = "The GCP region to host the resources"
  type        = string
  default     = "us-central1"
}

variable "bucket_name" {
  description = "The globally unique name for the Cloud Storage bucket"
  type        = string
}

# --- Storage Bucket ---

resource "google_storage_bucket" "private_bucket" {
  name          = var.bucket_name
  location      = var.region
  storage_class = "STANDARD"

  # Enforce uniform IAM-level access control
  uniform_bucket_level_access = true

  # Block all public access prevention policies
  public_access_prevention = "enforced"

  versioning {
    enabled = true
  }
}

# --- Service Account ---

resource "google_service_account" "storage_reader" {
  account_id   = "storage-object-reader"
  display_name = "Storage Object Reader"
  description  = "Dedicated service account with read-only object access to ${var.bucket_name}"
}

# --- IAM Binding ---

resource "google_storage_bucket_iam_member" "object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.storage_reader.email}"
}

# --- Outputs ---

output "bucket_name" {
  description = "The name of the created private storage bucket"
  value       = google_storage_bucket.private_bucket.name
}

output "bucket_url" {
  description = "The URI of the created private storage bucket"
  value       = google_storage_bucket.private_bucket.url
}

output "service_account_email" {
  description = "The email of the created reader service account"
  value       = google_service_account.storage_reader.email
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project and region can be configured here or inherited from environment variables.
}

# Service Account dedicated to reading objects from the bucket
resource "google_service_account" "bucket_reader" {
  account_id   = "bucket-reader-sa"
  display_name = "Storage Bucket Reader Service Account"
  description  = "Service account with read-only permissions on the private storage bucket"
}

# Private Cloud Storage bucket adhering to security best practices
resource "google_storage_bucket" "private_bucket" {
  name                     = "my-secure-private-bucket-${google_service_account.bucket_reader.account_id}"
  location                 = "US"
  uniform_bucket_level_access = true
  public_access_prevention = "enforced"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

# Grant read-only access (roles/storage.objectViewer) to the service account for the bucket
resource "google_storage_bucket_iam_member" "bucket_reader_object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.bucket_reader.email}"
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The Google Cloud Project ID"
}

variable "region" {
  type        = string
  description = "GCP Region for resources"
  default     = "us-central1"
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

resource "google_compute_network" "vpc" {
  name                    = "gke-vpc"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-subnet"
  ip_cidr_range            = "10.0.0.0/20"
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.4.0.0/14"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.8.0.0/20"
  }
}

# Cloud NAT is required for private nodes to egress to the internet (e.g., pull public images)
resource "google_compute_router" "router" {
  name    = "gke-router"
  region  = var.region
  network = google_compute_network.vpc.name
}

resource "google_compute_router_nat" "nat" {
  name                               = "gke-nat"
  router                             = google_compute_router.router.name
  region                             = var.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"
}

# ------------------------------------------------------------------------------
# Service Account for GKE Nodes
# ------------------------------------------------------------------------------

resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

resource "google_project_iam_member" "node_roles" {
  for_each = toset([
    "roles/logging.logWriter",
    "roles/monitoring.metricWriter",
    "roles/monitoring.viewer",
    "roles/stackdriver.resourceMetadata.writer"
  ])

  project = var.project_id
  role    = each.key
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# ------------------------------------------------------------------------------
# GKE Cluster (Private, Workload Identity)
# ------------------------------------------------------------------------------

resource "google_container_cluster" "primary" {
  name     = "private-gke-cluster"
  location = var.region

  # Remove default node pool to replace with a explicitly managed node pool
  remove_default_node_pool = true
  initial_node_count       = 1

  network    = google_compute_network.vpc.self_link
  subnetwork = google_compute_subnetwork.gke_subnet.self_link

  ip_allocation_policy {
    cluster_secondary_range_name  = google_compute_subnetwork.gke_subnet.secondary_ip_range[0].range_name
    services_secondary_range_name = google_compute_subnetwork.gke_subnet.secondary_ip_range[1].range_name
  }

  # Private Cluster Configuration
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Enable Workload Identity
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  deletion_protection = false
}

# ------------------------------------------------------------------------------
# GKE Node Pool
# ------------------------------------------------------------------------------

resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = var.region
  cluster    = google_container_cluster.primary.name
  node_count = 1

  node_config {
    machine_type = "e2-medium"

    service_account = google_service_account.gke_nodes.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    # Required for Workload Identity on nodes
    workload_metadata_config {
      mode = "GKE_METADATA"
    }

    metadata = {
      disable-legacy-endpoints = "true"
    }
  }
}

