terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Project and region can be configured via environment variables (e.g., GOOGLE_PROJECT, GOOGLE_REGION)
}

# BigQuery Dataset
resource "google_bigquery_dataset" "analytics" {
  dataset_id                  = "analytics_dataset"
  friendly_name               = "Analytics Dataset"
  description                 = "Dataset containing event tracking data"
  location                    = "US"
  default_table_expiration_ms = null # Tables will not expire by default

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

# BigQuery Table: events
resource "google_bigquery_table" "events" {
  dataset_id          = google_bigquery_dataset.analytics.dataset_id
  table_id            = "events"
  description         = "Event stream table"
  deletion_protection = false

  time_partitioning {
    type  = "DAY"
    field = "timestamp"
  }

  schema = jsonencode([
    {
      name        = "timestamp"
      type        = "TIMESTAMP"
      mode        = "REQUIRED"
      description = "The timestamp when the event occurred"
    },
    {
      name        = "user_id"
      type        = "STRING"
      mode        = "NULLABLE"
      description = "Unique identifier for the user triggering the event"
    }
  ])

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

