  name                = "mysql-public-instance"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # Requirement: Public IPv4 enabled for environments unable to use Cloud SQL Auth Proxy
      ipv4_enabled = true

      # Security best practice: Restrict public access to known office VPN network ranges
      # rather than opening to 0.0.0.0/0.
      authorized_networks {
        name  = "office-vpn"
        value = "198.51.100.0/24" # Update with the actual office VPN CIDR block
      }
    }
  }
}

