  name    = "router-asia-south1"
  region  = "asia-south1"
  network = google_compute_network.vpc.id
}

# Cloud NAT configuration to provide outbound internet access for private VMs
resource "google_compute_router_nat" "nat" {
  name                               = "nat-asia-south1"
  router                             = google_compute_router.router.name
  region                             = google_compute_router.router.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

# Terraform configuration for a MySQL Cloud SQL instance with public IP access
# constrained to an authorized network (e.g., Office VPN).

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
}

variable "region" {
  type        = string
  description = "The region to host the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  type        = string
  description = "CIDR block for the office VPN allowed to access the Cloud SQL instance publicly."
  default     = "203.0.113.50/32"
}

variable "db_username" {
  type        = string
  description = "Username for the initial database user."
  default     = "app_user"
}

variable "db_password" {
  type        = string
  description = "Password for the initial database user."
  sensitive   = true
}

provider "google" {
  project = var.project_id
  region  = var.region
}

resource "google_sql_database_instance" "mysql_instance" {
  name             = "mysql-public-instance"
  database_version = "MYSQL_8_0"
  region           = var.region

  # Set to true for production environments to avoid accidental deletion
  deletion_protection = false

  settings {
    tier = "db-n1-standard-1"

    ip_configuration {
      # Allocates a public IPv4 address to the Cloud SQL instance
      ipv4_enabled = true

      # Whitelist the office VPN CIDR to restrict public ingress
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }

      # Require SSL/TLS for all incoming connections
      ssl_mode = "ENCRYPTED_ONLY"
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }
  }
}

resource "google_sql_database" "database" {
  name     = "app_db"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_general_ci"
}

resource "google_sql_user" "user" {
  name     = var.db_username
  instance = google_sql_database_instance.mysql_instance.name
  password = var.db_password
  # Host pattern '%' allows access from the authorized VPN IP range
  host     = "%"
}

output "public_ip_address" {
  value       = google_sql_database_instance.mysql_instance.public_ip_address
  description = "The public IPv4 address assigned to the Cloud SQL instance."
}
